<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Customer Portal</title><style>:root{--bg:#0A1120;--surface:#121B2E;--border:#223252;--text:#E7EEF7;--muted:#8A99B5}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui}.wrap{max-width:960px;margin:auto;padding:24px}.card{background:var(--surface);border:1px solid var(--border);border-radius:16px;padding:22px;margin:14px 0}.row{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:14px}input{display:block;width:100%;max-width:420px;padding:11px;margin:8px 0;background:var(--bg);border:1px solid var(--border);border-radius:8px;color:var(--text)}button{padding:10px 14px;margin:4px;border:0;border-radius:8px;background:#16C4B0;color:#07111f;font-weight:700;cursor:pointer}.muted{color:var(--muted)}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style></head><body><main class="wrap"><h1>Customer Portal — Admin</h1><section class="card" id="login"><h2>Login Admin</h2><form id="loginForm"><input id="username" placeholder="Username" required><input id="password" type="password" placeholder="Password" required><button>Masuk</button></form><p id="loginMsg"></p></section><div id="panel" hidden><div class="row"><section class="card"><h2>Pengaturan</h2><input id="appName" placeholder="Nama aplikasi"><input id="appUrl" placeholder="URL aplikasi"><input id="genieacsUrl" placeholder="URL GenieACS"><button id="save">Simpan</button><p id="msg"></p></section><section class="card"><h2>Ubah akun admin</h2><input id="newUsername" placeholder="Username baru"><input id="currentPassword" type="password" placeholder="Password saat ini"><input id="newPassword" type="password" placeholder="Password baru"><button id="credentials">Simpan akun</button><p id="credentialMsg"></p></section></div><section class="card"><h2>WhatsApp gateway</h2><button id="wa">Status gateway</button><pre id="waResult"></pre></section><section class="card"><h2>Pelanggan</h2><button id="customers">Tampilkan</button><pre id="customerResult"></pre></section><section class="card"><h2>Audit log</h2><button id="logs">Tampilkan</button><pre id="logsResult"></pre></section><button id="logout">Keluar</button></div></main><script>const $=x=>document.getElementById(x);async function api(u,o={}){let r=await fetch(u,{headers:{'Content-Type':'application/json'},...o});let d=await r.json();if(!r.ok)throw Error(d.message||'Gagal');return d}async function init(){await api('/api/admin/status');$('login').hidden=true;$('panel').hidden=false;let d=await api('/api/admin/settings');$('appName').value=d.appName||'';$('appUrl').value=d.appUrl||'';$('genieacsUrl').value=d.genieacsUrl||''}init().catch(()=>{});$('loginForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/admin/auth/login',{method:'POST',body:JSON.stringify({username:$('username').value,password:$('password').value})});await init()}catch(e){$('loginMsg').textContent=e.message}};$('save').onclick=async()=>{try{await api('/api/admin/settings',{method:'PUT',body:JSON.stringify({appName:$('appName').value,appUrl:$('appUrl').value,genieacsUrl:$('genieacsUrl').value})});$('msg').textContent='Tersimpan'}catch(e){$('msg').textContent=e.message}};$('credentials').onclick=async()=>{try{await api('/api/admin/credentials',{method:'PUT',body:JSON.stringify({username:$('newUsername').value,currentPassword:$('currentPassword').value,newPassword:$('newPassword').value})});$('credentialMsg').textContent='Akun diperbarui'}catch(e){$('credentialMsg').textContent=e.message}};$('wa').onclick=async()=>{$('waResult').textContent=JSON.stringify(await api('/api/admin/whatsapp/status'),null,2)};$('customers').onclick=async()=>{$('customerResult').textContent=JSON.stringify(await api('/api/admin/customers'),null,2)};$('logs').onclick=async()=>{$('logsResult').textContent=JSON.stringify(await api('/api/admin/logs'),null,2)};$('logout').onclick=async()=>{await api('/api/admin/auth/logout',{method:'POST'});location.reload()};</script></body></html>